	{ "img", "speditor/help/browser.jpg", "The model browser: search, categories, addons and games the models come from.", "Браузер моделей: поиск, категории, аддоны и игры, из которых модели." },
	{ "img", "speditor/help/browser_preview.jpg", "The preview of the model browser: Alyx under the cursor, turning in her idle animation, with her file name and number of bones.",
