-- an example scene: asks first when the current scene has objects (loading replaces it)
local function loadExample(name)
	if #C.Objects() == 0 then
		C.SceneLoad(name)
		return
	end
	Derma_Query(string.format(L("load_confirm"), name), "Garry's Mod Filmmaker", L("load"), function() C.SceneLoad(name) end, L("cancel"), function() end)
end

